<template>
  <el-tree
    :data="options"
    :props="props"
    :default-checked-keys="defaultCheckedKeys"
    :check-strictly="true"
    show-checkbox
    node-key="value"
    ref="tree"
    @check-change="handleCheckChange"
  ></el-tree>
</template>

<script>
import { option } from "./option";

export default {
  data() {
    return {
      options: option,
      props: {
        label: "label",
        children: "children",
        disabled: "disabled",
      },
      defaultCheckedKeys: [],
    };
  },
  methods: {
    // 处理勾选变化事件
    handleCheckChange() {
      // 获取当前树上选中的所有叶子节点value值并保存到数组中
      const checkedLeafKeys = this.$refs.tree.getCheckedKeys(true, true);
      this.defaultCheckedKeys = checkedLeafKeys;
    },
  },
};
</script>

