function [ucost, ttake] = takeoff(ptake, ftake, materials)
    % Obtaining the number of months in the past and future
    numOfPastMonths = size(ptake, 1);
    numOfFutureMonths = size(ftake, 1);
    numOfMaterials = size(ftake, 2);

    % Initializing the unit cost array
    ucost = zeros(1, numOfMaterials);

    % Checking if the number of past months is enough to determine unit costs
    if numOfPastMonths < numOfMaterials
        ttake = 'Info is not enough';
        return;
    end

    % Finding unit cost for each material
    for i = 1:numOfMaterials
        % Calculate coefficients matrix for the system of linear equations
        coefMatrix = ptake(1:numOfMaterials, 1:numOfMaterials);

        % Calculate the constant matrix
        constMatrix = ptake(1:numOfMaterials, end)';

        % Solving the system of linear equations
        ucost = linsolve(coefMatrix, constMatrix);
    end

    % Initializing the ttake cell array
    ttake = cell(numOfMaterials + 1, numOfFutureMonths + 1);

    % Storing material names and quantities for each month
    ttake(2:end, 1) = materials';
    ttake(1:end-1, 2:end-1) = ftake;

    % Calculating total cost for future months
    totalCost = sum(cell2mat(ftake) .* ucost', 2);

    % Storing total cost in ttake
    ttake(1, end) = {'cost'};
    ttake(2:end, end) = num2cell(totalCost);
end
