#include <windows.h>
#include <tchar.h>
```

2. Define a window class and register it:

```c++
// This struct is used to hold the data of our window class
struct WindowClassData
{
    UINT style;
    WNDPROC lpfnWndProc;
    int cbClsExtra;
    int cbWndExtra;
    HINSTANCE hInstance;
    HICON hIcon;
    HCURSOR hCursor;
    HBRUSH hbrBackground;
    LPCTSTR lpszMenuName;
    LPCTSTR lpszClassName;
};

// Register the window class with the given data
void RegisterWindowClass(WindowClassData& wndClassData)
{
    WNDCLASS wc = {};
    wc.style = wndClassData.style;
    wc.lpfnWndProc = wndClassData.lpfnWndProc;
    wc.cbClsExtra = wndClassData.cbClsExtra;
    wc.cbWndExtra = wndClassData.cbWndExtra;
    wc.hInstance = wndClassData.hInstance;
    wc.hIcon = wndClassData.hIcon;
    wc.hCursor = wndClassData.hCursor;
    wc.hbrBackground = wndClassData.hbrBackground;
    wc.lpszMenuName = wndClassData.lpszMenuName;
    wc.lpszClassName = wndClassData.lpszClassName;

    RegisterClass(&wc);
}

// Create the window class data and register the window class
void CreateWindowClass(HINSTANCE hInstance, LPCTSTR className, WNDPROC wndProc)
{
    WindowClassData wndClassData = {};
    wndClassData.style = CS_HREDRAW | CS_VREDRAW;
    wndClassData.lpfnWndProc = wndProc;
    wndClassData.hInstance = hInstance;
    wndClassData.hCursor = LoadCursor(NULL, IDC_ARROW);
